mapper.select:
SELECT ID,DEVICE_ID,OPERATION,FAIR_KEY FROM (
  SELECT q.* FROM (SELECT ph.ID,ph.DEVICE_ID,
    CASE WHEN ph.PHASE IN ('DIRECT_SEND','ISC_CONFIG') AND ph.STATE='PREPARED' THEN 'SUBMIT'
      WHEN ph.PHASE='ISC_CONFIG' THEN 'CONFIG_PROGRESS' WHEN ph.STATE='PREPARED' THEN 'DOWNLOAD' ELSE 'RECEIPT' END OPERATION,
    LPAD(TO_CHAR(ph.PARK_ID),10,'0')||':'||ph.DEVICE_ID FAIR_KEY
    FROM SMT_AUTH_TRANSPORT_PHASE ph JOIN SMT_AUTH_OPERATION_TARGET t ON t.ID=ph.TARGET_ID JOIN SMT_AUTH_OPERATION_BATCH b ON b.ID=t.BATCH_ID
    WHERE ph.INSTANCE_ID=#{p.instanceId} AND ph.PARK_ID IN  AND ph.ACCESS_TYPE=#{p.accessType} AND ()=#{priority}

      AND ph.PHASE IN ('DIRECT_SEND','ISC_CONFIG') AND ph.STATE='PREPARED' AND ()=#{lane}
      AND ((ph.PHASE='ISC_CONFIG' AND ph.STATE='ACCEPTED') OR (ph.PHASE='ISC_DOWNLOAD' AND ph.STATE='PREPARED'))
      AND ph.PHASE='ISC_DOWNLOAD' AND ph.STATE='ACCEPTED'

    AND COALESCE((SELECT USED FROM SMT_AUTH_SCHEDULER_QUOTA r WHERE r.INSTANCE_ID=#{p.instanceId} AND r.PARK_ID=ph.PARK_ID AND r.DEVICE_ID=ph.DEVICE_ID
      AND r.SCOPE_TYPE='DEVICE' AND r.LANE=#{lane} AND r.WINDOW_KEY=#{window}),0)+#{cost}
      <= FLOOR(#{p.deviceHttpPerSecond}*31/8)
  ) q ORDER BY CASE WHEN #{after,jdbcType=VARCHAR} IS NULL OR FAIR_KEY > #{after,jdbcType=VARCHAR} THEN 0 ELSE 1 END,FAIR_KEY,CASE WHEN #{afterId,jdbcType=NUMERIC} IS NULL OR ID > #{afterId,jdbcType=NUMERIC} THEN 0 ELSE 1 END,ID
) WHERE ROWNUM<=1

mapper.update:
UPDATE SMT_AUTH_OPERATION_TARGET SET NEXT_ATTEMPT_AT=#{retryAt},UPDATE_TIME=#{now}
WHERE ID IN(SELECT ID FROM(SELECT t.ID FROM SMT_AUTH_OPERATION_TARGET t JOIN SMT_AUTH_OPERATION_BATCH b ON b.ID=t.BATCH_ID
  WHERE  AND t.DEVICE_ID=#{p.selectedDevice} AND t.STATE='QUEUED' AND ()=#{priority}
    AND (t.NEXT_ATTEMPT_AT IS NULL OR t.NEXT_ATTEMPT_AT<=#{now})
    AND (SELECT COUNT(*) FROM SMT_AUTH_OPERATION_TARGET a WHERE a.PARK_ID=t.PARK_ID AND a.ACCESS_TYPE=t.ACCESS_TYPE AND a.DEVICE_ID=t.DEVICE_ID AND a.STATE IN('EXECUTING','WAITING_CONFIRM','VERIFYING'))>=#{p.perDeviceInflight}
  ORDER BY t.ID) WHERE ROWNUM<=#{limit}) AND STATE='QUEUED'

mapper.select:
SELECT ID FROM (SELECT b.ID FROM SMT_AUTH_OPERATION_BATCH b WHERE b.STATUS='PREPARING' AND b.PARK_ID IN 
  AND EXISTS(SELECT 1 FROM SMT_AUTH_SELECTION_SOURCE s WHERE s.BATCH_ID=b.ID)
  AND CASE WHEN b.ACTION='DELETE' OR EXISTS(SELECT 1 FROM SMT_AUTH_SELECTION_SOURCE s WHERE s.BATCH_ID=b.ID AND s.DESIRED_ACTION='DELETE') THEN 'DELETE' ELSE 'ADD' END=#{priority}
  AND b.ID>#{after} ORDER BY b.ID) WHERE ROWNUM<=#{limit}

SELECT * FROM (SELECT * FROM SMT_AUTH_SCHEDULER_JOB WHERE INSTANCE_ID=#{id}
  AND (LANE IN ('EXPAND','EXPIRE','RECOVER','CONVERGE','REFRESH') OR LANE LIKE 'ADD:%' OR LANE LIKE 'DELETE:%' OR LANE LIKE 'CONFIG:%' OR LANE LIKE 'RECEIPT:%')
  ORDER BY LANE) WHERE ROWNUM<=405

SELECT ID FROM (SELECT t.ID FROM SMT_AUTH_OPERATION_TARGET t WHERE 
  AND t.STATE='EXECUTING' AND t.LEASE_UNTIL <=#{now}
  AND EXISTS(SELECT 1 FROM SMT_AUTH_OPERATION_ATTEMPT a WHERE a.TARGET_ID=t.ID AND a.LEASE_TOKEN=t.LEASE_TOKEN AND a.STATUS='CLAIMED')
  AND t.ID >#{after} ORDER BY t.ID) WHERE ROWNUM <=#{limit}

mapper.update:
UPDATE SMT_AUTH_OPERATION_TARGET t SET STATE='QUEUED',LEASE_TOKEN=NULL,LEASE_UNTIL=NULL,NEXT_ATTEMPT_AT=#{now},UPDATE_TIME=#{now}
    WHERE t.ID=#{id} AND t.STATE='EXECUTING' AND t.LEASE_UNTIL <=#{now}
      AND EXISTS(SELECT 1 FROM SMT_AUTH_OPERATION_ATTEMPT a WHERE a.TARGET_ID=t.ID AND a.LEASE_TOKEN=t.LEASE_TOKEN AND a.STATUS='EXPIRED')
